1	/**
2	 * Wiring. Everything above is injectable; this is the one place that decides
3	 * which real implementations get used.
4	 */
5	
6	import type { Clock } from "./clock.ts";
7	import { SystemClock } from "./clock.ts";
8	import type { Config } from "./config.ts";
9	import { loadConfig } from "./config.ts";
10	import { IngestQueue } from "./ingest.ts";
11	import { MemoryStore } from "./store.ts";
12	import type { Router } from "./router.ts";
13	import { createRouter } from "./router.ts";
14	
15	export interface Service {
16	  config: Config;
17	  store: MemoryStore;
18	  queue: IngestQueue;
19	  router: Router;
20	  /** Move queued samples into the store and expire anything past retention. */
21	  tick(): void;
22	}
23	
24	export function createService(
25	  config: Config = loadConfig(),
26	  clock: Clock = new SystemClock(),
27	): Service {
28	  const store = new MemoryStore(config.maxSamples);
29	  const queue = new IngestQueue(config.maxSamples);
30	  const router = createRouter(store, config, clock);
31	
32	  return {
33	    config,
34	    store,
35	    queue,
36	    router,
37	    tick(): void {
38	      for (const sample of queue.drain()) store.put(sample);
39	      store.prune(clock.now() - config.retentionMs);
40	    },
41	  };
42	}
43	
44	export function main(): void {
45	  const service = createService();
46	  const series = service.store.series();
47	  process.stdout.write(
